package main
import("database/sql";"fmt";"log";"os";"encoding/binary";_ "github.com/go-sql-driver/mysql")
func main(){db,e:=sql.Open("mysql","isucon:isucon@tcp(127.0.0.1:3306)/isupipe");if e!=nil{log.Fatal(e)};runes:=make([]rune,0,65536);for i:=rune(0);i<65536;i++{if i>=0xd800&&i<=0xdfff{continue};runes=append(runes,i)};var b []byte;if e=db.QueryRow("SELECT WEIGHT_STRING(? COLLATE utf8mb4_general_ci)",string(runes)).Scan(&b);e!=nil{log.Fatal(e)};if len(b)!=2*len(runes){log.Fatalf("unexpected weight bytes %d vs %d",len(b),len(runes)*2)};out:=make([]byte,131072);for i,r:=range runes{copy(out[int(r)*2:],b[i*2:i*2+2])};if e=os.WriteFile("/tmp/general-ci.bin",out,0644);e!=nil{log.Fatal(e)};for _,s:=range []string{"😀","𐐀","𐐨"}{var x []byte;if e=db.QueryRow("SELECT WEIGHT_STRING(? COLLATE utf8mb4_general_ci)",s).Scan(&x);e!=nil{log.Fatal(e)};fmt.Printf("%s %x %d\n",s,x,binary.BigEndian.Uint16(x))}}
